import { useEffect, useId, useRef, useState } from 'react';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import '@kerfjs/ui/layout.css';
import './command-palette.css';

// Available context names DialogHeader and EmptyState but no verified palette export.
// This local semantic composition avoids inventing an upstream CommandPalette API.
export type Command = { id: string; label: string; group: string; run: () => void };
export function CommandPalette({ open, commands, recentIds, remember, close }: {
  open: boolean; commands: readonly Command[]; recentIds: readonly string[];
  remember: (id: string) => void; close: () => void;
}) {
  const id = useId();
  const modal = useRef<HTMLDialogElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const [query, setQuery] = useState('');
  const [activeId, setActiveId] = useState<string | null>(null);
  const matching = commands.filter(c => c.label.toLocaleLowerCase().includes(query.toLocaleLowerCase()));
  const recent = query ? [] : recentIds.map(key => commands.find(c => c.id === key)).filter((c): c is Command => !!c);
  const groups = new Map<string, Command[]>();
  if (recent.length) groups.set('Recent commands', recent);
  matching.filter(c => !recent.some(r => r.id === c.id)).forEach(c => {
    const key = c.group || 'Commands';
    groups.set(key, [...(groups.get(key) || []), c]);
  });
  const flat = [...groups.values()].flat();
  const active = flat.find(c => c.id === activeId) || flat[0];
  const optionId = (command: Command) => id + '-option-' + flat.indexOf(command);
  function choose(command: Command) {
    remember(command.id);
    close();
    command.run();
  }
  useEffect(() => {
    if (!open) { if (modal.current?.open) modal.current.close(); return; }
    const previous = document.activeElement as HTMLElement | null;
    setQuery(''); setActiveId(null);
    modal.current?.showModal();
    input.current?.focus();
    return () => { modal.current?.close(); if (previous?.isConnected) previous.focus(); };
  }, [open]);
  useEffect(() => {
    if (active) document.getElementById(optionId(active))?.scrollIntoView({ block: 'nearest' });
  }, [active?.id, query]);
  return <dialog ref={modal} className="kui-layout command-palette"
    aria-labelledby={id + '-title'}
    onCancel={event => { event.preventDefault(); close(); }}>
    <DialogHeader title={<span id={id + '-title'}>Run a command</span>} />
    <div className="kui-dialog-body command-body">
      <label htmlFor={id + '-input'}>Search commands</label>
      <input id={id + '-input'} ref={input} role="combobox" aria-autocomplete="list"
        aria-expanded={open} aria-controls={id + '-results'}
        aria-activedescendant={active ? optionId(active) : undefined}
        value={query} onChange={event => { setQuery(event.target.value); setActiveId(null); }}
        onKeyDown={event => {
          if (event.nativeEvent.isComposing) return;
          if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
            event.preventDefault();
            if (!flat.length) return;
            const index = active ? flat.indexOf(active) : 0;
            setActiveId(flat[(index + (event.key === 'ArrowDown' ? 1 : -1) + flat.length) % flat.length].id);
          } else if (event.key === 'Enter' && active) {
            event.preventDefault(); choose(active);
          }
        }} />
      <div id={id + '-results'} role="listbox" aria-label="Commands" className="command-results">
        {[...groups].map(([group, entries], groupIndex) => <div role="group" key={group} aria-labelledby={id + '-group-' + groupIndex}>
          <div id={id + '-group-' + groupIndex}>{group}</div>
          {entries.map(command => <div key={command.id} id={optionId(command)} role="option"
            aria-selected={command.id === active?.id} className="command-option"
            onPointerMove={() => setActiveId(command.id)}
            onMouseDown={event => event.preventDefault()} onClick={() => choose(command)}>
            {command.id === active?.id && <span aria-hidden="true">› </span>}{command.label}
          </div>)}
        </div>)}
      </div>
      {flat.length === 0 && <EmptyState title="No matching commands" description="Try a different search." />}
      <span role="status" aria-live="polite">{flat.length} commands available</span>
    </div>
    <footer><button type="button" onClick={close}>Close</button></footer>
  </dialog>;
}

