.command-palette { inline-size:min(38rem,calc(100vw - 2rem)); max-block-size:calc(100dvh - 2rem); padding:0; overflow:hidden; }
.command-palette[open] { display:flex; flex-direction:column; }
.command-body { min-block-size:0; overflow:auto; }
.command-body input { inline-size:100%; box-sizing:border-box; min-block-size:2.75rem; }
.command-option { min-block-size:2.75rem; display:flex; align-items:center; cursor:pointer; overflow-wrap:anywhere; }
.command-option[aria-selected=true] { outline:2px solid currentColor; outline-offset:-2px; font-weight:600; }
:focus-visible { outline:2px solid currentColor; outline-offset:2px; }
